      gl.enable(gl.CULL_FACE);gl.cullFace(gl.FRONT);gl.uniform1f(h.flip,-1);gl.uniform1f(h.refl,1);S.drawHorse();gl.disable(gl.CULL_FACE);
      gl.clear(gl.DEPTH_BUFFER_BIT);gl.disable(gl.DEPTH_TEST);
